import {Footer} from "@/components/Footer";import {Header} from "@/components/Header";import {VehicleCard} from "@/components/VehicleCard";import {getDealer,getVehicles} from "@/lib/api";
export default async function Inventory({searchParams}:{searchParams:Promise<Record<string,string|undefined>>}){const p=await searchParams;const query=new URLSearchParams();for(const [k,v] of Object.entries(p))if(v)query.set(k,v);const [dealer,vehicles]=await Promise.all([getDealer(),getVehicles(query.toString())]);return <><Header dealer={dealer}/><main id="main" style={{"--brand":dealer.primary_color} as React.CSSProperties}><section className="pageIntro"><span className="eyebrow">Current collection</span><h1>Find the car that fits.</h1><p>{vehicles.length} carefully presented vehicles.</p></section><form className="filters"><label>Search<input type="search" name="q" defaultValue={p.q} placeholder="Make, model, keyword"/></label><label>Status<select name="availability" defaultValue={p.availability}><option value="">All states</option><option value="available">Available</option><option value="reserved">Reserved</option><option value="sold">Sold</option></select></label><label>Sort<select name="sort" defaultValue={p.sort}><option value="newest">Newest</option><option value="price_low">Price: low to high</option><option value="price_high">Price: high to low</option></select></label><button className="button">Apply</button></form><section className="section vehicleGrid">{vehicles.length?vehicles.map(v=><VehicleCard key={v.id} vehicle={v}/>):<div className="empty"><h2>No cars match those filters.</h2><p>Try removing a filter.</p></div>}</section></main><Footer dealer={dealer}/></>}
